package com.codecrafters.kehdona.data.profile

/**
 * A member's private profile. [name] is the name the person typed (or explicitly
 * confirmed) themselves; nothing generated by an AI is ever written to it automatically.
 */
data class UserProfile(
    val uid: String,
    val name: String,
    val email: String?,
    val phoneNumber: String?,
    val personalityProfile: String? = null,
    val personalitySkipped: Boolean = false,
)

class ProfileException(message: String, cause: Throwable? = null) : Exception(message, cause)

/** Stores profiles in Firestore at `users/{uid}`. Every function throws [ProfileException]. */
interface ProfileRepository {
    suspend fun getProfile(uid: String): UserProfile?

    /**
     * Creates the profile. If it already exists, only [UserProfile.name] is applied; the
     * original creation time and contact details are never overwritten.
     */
    suspend fun createProfile(profile: UserProfile)

    /** Only called after the person explicitly confirms a name change. */
    suspend fun updateName(uid: String, name: String)

    suspend fun savePersonality(uid: String, profileText: String)

    suspend fun skipPersonality(uid: String)
}
